mat2 creerMatriceRotation(float angle) {
    float cosinus = cos(angle);
    float sinus = sin(angle);
    return mat2(cosinus, -sinus, sinus, cosinus);
}

float calculerMotifPetale(vec2 position, float indexCouche, float temps) {
    float rayon = length(position);
    float angle = atan(position.y, position.x);

    vec2 directionVent = vec2(0.8, 0.5);

    float rafale = sin(temps * 1.5) * 0.5 + cos(temps * 3.2) * 0.3 + 0.8;

    float flexibilite = pow(rayon, 1.8);

    vec2 deplacementVent = directionVent * rafale * flexibilite * 0.12;
    position -= deplacementVent;

    rayon = length(position);
    angle = atan(position.y, position.x);

    float turbulence = sin(angle * 8.0 + temps * 4.0 + indexCouche) * 0.03 * flexibilite;
    float battement = sin(temps * 2.5 + indexCouche * 0.4 + angle * 3.0) * 0.05 * flexibilite;

    rayon += turbulence + battement;

    vec2 deplacement = vec2(
        sin(rayon * 2.6 + indexCouche * 1.2),
        cos(rayon * 3.4)
    ) * 0.02;
    position += deplacement;

    float nombrePetales = floor(3.0 + mod(indexCouche, 3.0));

    float valeurPetale = mix(abs(sin(angle)) * 0.5, sin(nombrePetales * angle), 1.0) * (1.0 - rayon);

    return smoothstep(0.2, 0.16, abs(valeurPetale - 0.5));
}

vec3 calculerCouleurCouche(float indexCouche, float rayon, float contourPetale) {
    vec3 couleurRoseIntense = vec3(1.0, 0.2, 0.4);
    vec3 couleurRosePastel = vec3(1.0, 0.7, 0.8);

    float facteurMelange = sin(indexCouche + rayon * 8.0);
    vec3 couleurAcouche = mix(couleurRoseIntense, couleurRosePastel, facteurMelange);

    float masqueDistance = smoothstep(0.0, 0.0, 0.8 - rayon);
    float facteurEchelle = pow(0.98, indexCouche);

    return contourPetale * couleurAcouche * masqueDistance * facteurEchelle * 1.5;
}

vec3 calculerBulbe(vec2 uv, float temps, out float masqueVisibilite) {
    float rayon = length(uv);
    float angle = atan(uv.y, uv.x);

    masqueVisibilite = smoothstep(0.15, 0.01, rayon);

    float detailsGranuleux = sin(angle * 12.0) * cos(rayon * 40.0);
    detailsGranuleux += sin(angle * 24.0 + temps) * 0.5;

    vec3 couleurJauneVif = vec3(1.0, 0.85, 0.0);
    vec3 couleurOrangeAmbre = vec3(0.95, 0.4, 0.0);

    float gradientRadiique = clamp(rayon * 7.0 + detailsGranuleux * 0.15, 0.0, 1.0);
    vec3 couleur = mix(couleurJauneVif, couleurOrangeAmbre, gradientRadiique);

    couleur += vec3(0.4, 0.3, 0.0) * smoothstep(0.05, 0.0, rayon);

    return couleur;
}

void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    vec2 uv = (coordFragment - 0.5 * iResolution.xy) / iResolution.y;
    float temps = iTime;

    float zoom = 1.0 + sin(temps * 0.3) * 0.15;

    vec2 deplacementCamera = vec2(
        sin(temps * 0.4) * 0.04 + cos(temps * 0.25) * 0.02,
        cos(temps * 0.35) * 0.04 + sin(temps * 0.18) * 0.02
    );

    float roulisCamera = sin(temps * 0.2) * 0.05;

    vec2 uvNormalisees = (uv - deplacementCamera) * zoom * creerMatriceRotation(roulisCamera);

    vec3 couleurAccumulee = vec3(0.0);

    for (float indexCouche = 0.0; indexCouche < 32.0; indexCouche++) {
        float facteurEchelle = pow(0.98, indexCouche);
        float angleRotation = indexCouche * 0.15;

        vec2 positionLayer = (uvNormalisees / facteurEchelle) * creerMatriceRotation(angleRotation);

        float rayon = length(positionLayer);
        float contourPetale = calculerMotifPetale(positionLayer, indexCouche, temps);

        couleurAccumulee += calculerCouleurCouche(indexCouche, rayon, contourPetale);
    }

    vec3 couleurPetales = tanh(couleurAccumulee * 0.3);

    float masqueBulbe = 0.0;
    vec3 couleurBulbe = calculerBulbe(uvNormalisees, temps, masqueBulbe);

    vec3 couleurFinale = mix(couleurPetales, couleurBulbe, masqueBulbe);

    float distCentre = length(uv);
    float flouLens = smoothstep(0.35, 0.7, distCentre);
    couleurFinale = mix(couleurFinale, vec3(dot(couleurFinale, vec3(0.299, 0.587, 0.114))), flouLens * 0.25);

    float vignettage = smoothstep(0.8, 0.2, distCentre * 0.9);
    couleurFinale *= vignettage;

    couleurFragment = vec4(couleurFinale, 1.0);
}
